+    control.postMessage({ action, id, fail });
+    await settle(
+      () =>
+        messages
+          .slice(after)
+          .some(
+            (message) => message.type === 'ack' && message.action === action && message.id === id,
+          ),
+      'The loader ownership control must acknowledge its command.',
+      { timeoutMs: 5000 },
+    );
+  };
+  const start = (
+    result = { url: panelURL },
+    parent = parentURL,
+    failure = null,
