+      await settle(() => retried.settled, 'The later resolver must settle.', { timeoutMs: 5000 });
+      assert.equal(retried.value, firstResult);
+      assert.equal(retried.error, null);
+      assert.equal(gate.loader.hasRef(), false);
+    },
+  );
+}
+
+test(
